props.onDataChangeTransform:
/* TableShipmentSorting On Data Change */
$isNotNilOrEmpty(data) and $not(data = prevData) ?
  (
    $shipments := $$.data#$index.($~>|$|{
      'sequence': $index + 1
    }|)^(sequence);
    $components.ScreenCreateLoadForm.fn.setContextValue('load.shipments', [$shipments]);
    $components.TableShipmentSorting.fn.setData([$shipments]);
  )
  /* : data */
